/** Stable, deliberately redacted form representation for the local runner.
 * DOM ids are often regenerated by React, so field_id is based on the question
 * plus its occurrence on this step. */
import { normalizeKey, isSensitiveQuestion, isOtpVerificationQuestion } from './matcher.js';
import { readValue } from './engine.js';
import { isResumeInput } from './filler.js';

// Ordinary terms, privacy, demographic processing, and the standard accuracy
// attestation are deterministic consent controls when an exact stored answer
// exists. Credentials and AI disclosures remain separately classified by the
// runner's final policy gate.
const SALARY = /\b(?:salary|compensation|expected pay|desired pay|pay range|compensation range|base pay|total (?:target )?comp(?:ensation)?|target cash|annual bonus|bonus expectation|equity (?:expectation|grant|compensation)|(?:rsu|stock option)s? (?:expectation|grant|compensation))\b/i;
const CURRENT_COMPENSATION = /\b(?:current|present|most recent|prior|previous)\b(?:\s+\w+){0,3}\s+(?:base\s+)?(?:salary|compensation|pay|earnings?|bonus|equity|stock|rsu(?:s)?|options?)\b|\bwhat (?:do|did) you (?:make|earn)\b/i;
const EQUITY_NON_DOLLAR_UNIT = /\b(?:number of )?(?:shares|options|rsus?)\b|\bequity\s*(?:percentage|%)\b|\bpercentage\s+of\s+(?:the )?company\b/i;
const REVIEW = /assessment|take.?home|captcha|contact/i;
const DETERMINISTIC = /citizen|work authorization|authorized to work|sponsorship|visa|gender|cisgender|transgender|race|ethnicity|veteran|disability|relocat|availability|able to start|start a new role|hybrid capacity|report to the office|how soon.{0,40}start|desired start date|earliest start|expected graduation|graduation date|gpa \(|\bsat score\b|\bact score\b|\bgre score\b|employment history|essential functions|reasonable accommodation|export compliance|u\.?s\.? person|f1 opt|opt\/cpt/i;
const AMBIGUOUS_IDENTITY_LABEL = /^\s*i\s+identify\s+as\s*:?\s*$/i;
// This intentionally targets optional recruiting/marketing permission, not
// operational contact about this application.  A stored answer must never
// turn a voluntary talent-community or job-alert opt-in into consent.
const OPTIONAL_MARKETING_CONSENT = /(?:marketing|talent\s*(?:community|network|pool)|future\s+(?:job|career|employment|opportunit)|future\s+opportunit|job\s*alerts?|newsletters?|promotional|recruit(?:ing|ment)\s+updates?|contact\s+me\s+(?:about|for)\s+(?:other|future)|keep\s+(?:me\s+)?informed)/i;

export function isOptionalMarketingConsent(question = '', options = []) {
  return OPTIONAL_MARKETING_CONSENT.test([question, ...(Array.isArray(options) ? options : [])].join(' '));
}

const FUTURE_OPPORTUNITY_DECLINE = /^(?:no)\b|do not (?:wish|want)|not interested|decline/i;
const FUTURE_OPPORTUNITY_OPT_IN = /\b(?:yes|keep me informed|job alerts?|sign me up|subscribe)\b/i;

function optionLabel(option) {
  if (typeof option === 'string') return option;
  return String(option?.text || option?.value || '');
}

/** Always decline future-opportunity / marketing prompts when a No option exists. */
export function mapFutureOpportunityChoice(question, options = []) {
  if (!isOptionalMarketingConsent(question, options)) return null;
  const labels = (Array.isArray(options) ? options : []).map(optionLabel).filter(Boolean);
  if (!labels.length) return 'No';
  const nos = labels.filter(label => FUTURE_OPPORTUNITY_DECLINE.test(label) && !FUTURE_OPPORTUNITY_OPT_IN.test(label));
  return nos.length === 1 ? nos[0] : null;
}

export function riskCategory(question = '', options = []) {
  // Some ATSes label a gender-identity question only "I identify as". Its
  // controlled choices carry the missing meaning, and are safe metadata to
  // inspect locally. Never demote that field to LOW merely because the label
  // is terse.
  const context = [question, ...(Array.isArray(options) ? options : [])].join(' ');
  if (isOtpVerificationQuestion(question) || isOtpVerificationQuestion(context)) return 'EPHEMERAL';
  if (isOptionalMarketingConsent(question, options)) return 'OPTIONAL_CONSENT';
  if (CURRENT_COMPENSATION.test(context)) return 'CURRENT_COMPENSATION';
  // The runtime keeps share-count and percentage requests review-only. Mark
  // them as compensation here so the global answer bank cannot fill them.
  if (EQUITY_NON_DOLLAR_UNIT.test(context)) return 'SALARY';
  if (SALARY.test(context)) return 'SALARY';
  if (REVIEW.test(context)) return 'REVIEW';
  if (AMBIGUOUS_IDENTITY_LABEL.test(question) || DETERMINISTIC.test(context) || isSensitiveQuestion(context)) return 'DETERMINISTIC_ONLY';
  if (/essay|cover letter|why (?:do you|are you)|describe|tell us|additional information/i.test(question)) return 'CUSTOM_PROSE';
  return 'LOW';
}

function constraints(field) {
  const el = field.control;
  const number = value => Number.isFinite(Number(value)) ? Number(value) : null;
  return {
    min_length: number(el.getAttribute('minlength')),
    max_length: number(el.getAttribute('maxlength')),
    pattern: el.getAttribute('pattern') || null,
    accepts: el.getAttribute('accept') || null,
  };
}

export function fieldDescriptors(fields) {
  const seen = new Map();
  return fields.map(field => {
    const normalized_question = normalizeKey(field.rawLabel);
    const occurrence = (seen.get(normalized_question) || 0) + 1;
    seen.set(normalized_question, occurrence);
    const options = (field.options || []).map(option => String(option.text || option.value || '')).filter(Boolean);
    const classifiedRisk = riskCategory(field.rawLabel, options);
    // Wording such as "How would you describe ... (Select one)" names a
    // controlled choice, not an invitation to generate prose. Some React
    // comboboxes expose their options only after interaction, so the empty
    // descriptor option list cannot be used to infer the control's intent.
    const controlledChoice = ['select', 'radio', 'checkbox', 'buttongroup', 'combobox', 'combobox-input']
      .includes(field.kind);
    const risk = classifiedRisk === 'CUSTOM_PROSE' && controlledChoice ? 'LOW' : classifiedRisk;
    const value = readValue(field);
    return {
      field_id: `${normalized_question || 'unlabelled'}:${field.kind}:${field.groupIndex ?? 'root'}:${occurrence}`,
      question: field.rawLabel,
      normalized_question,
      type: field.kind,
      // A generic visual label such as Greenhouse's "Attach" is not enough to
      // distinguish resume and cover-letter controls. Carry the locally
      // resolved slot role over the bridge without exposing a DOM identifier.
      file_role: field.kind === 'file'
        ? (isResumeInput(field.control, field.rawLabel) ? 'resume' : 'other')
        : null,
      options,
      constraints: constraints(field),
      required: field.required === true,
      occurrence,
      risk,
      // Never send sensitive current values over the extension bridge.
      current_value: (risk === 'DETERMINISTIC_ONLY' || risk === 'EPHEMERAL') ? (value ? '[present]' : '')
        : String(value || '').slice(0, risk === 'CUSTOM_PROSE' ? 4000 : 500),
    };
  });
}

export function navigationState(root = document) {
  const text = String(root.body?.innerText || root.documentElement?.innerText || '').slice(0, 12000);
  const controls = [...root.querySelectorAll?.('button, input[type="submit"], [role="button"]') || []];
  const buttonText = controls
    .map(el => `${el.textContent || ''} ${el.value || ''}`.trim()).join(' ');
  // A provider badge is not a CAPTCHA challenge. Greenhouse commonly displays
  // a small reCAPTCHA badge in the corner, and Ashby mounts an invisible frame
  // on every form. Both are safe to fill. A real checkbox/image challenge or
  // explicit verification prompt remains a hard stop.
  const visibleCaptchaFrame = [...root.querySelectorAll?.('iframe[src*="captcha" i]') || []].some(el => {
    const style = root.defaultView?.getComputedStyle?.(el);
    if (style && (style.display === 'none' || style.visibility === 'hidden')) return false;
    // Greenhouse's enterprise token frame advertises `size=invisible` even
    // while it reserves a small badge-sized rectangle. It is not an
    // interactive challenge. A later bframe or a visible prompt is still
    // detected below and blocks the run.
    if (/[?&]size=invisible(?:&|$)/i.test(el.src || '')) return false;
    const rect = el.getBoundingClientRect?.();
    // A badge is normally about 70px wide. Interactive provider widgets are
    // at least the width of a checkbox/image challenge. Unknown geometry is
    // treated as a challenge so a hostile portal cannot hide its dimensions.
    return !rect || rect.width >= 160 || rect.height >= 100;
  });
  const captchaPrompt = /(?:verify (?:you are|that you are)|i'?m not a robot|select (?:all )?(?:images|squares)|security check|challenge (?:expired|required)|complete (?:the )?(?:captcha|recaptcha|hcaptcha))/i.test(text);
  // Do not treat ordinary prose such as "50 million registered users" or
  // "co-create" as an account-creation gate.  Only an actual sign-up control,
  // an account-creation heading, or a credential form with sign-up language
  // may stop an application.  This keeps Greenhouse job descriptions from
  // falsely blocking their own application form.
  const credentialInput = root.querySelector?.('input[type="password"]');
  const accountControl = controls.some(el => /^(?:create (?:an )?account|register|sign up)$/i
    .test(`${el.textContent || ''} ${el.value || ''}`.replace(/\s+/g, ' ').trim()));
  const accountHeading = [...root.querySelectorAll?.('h1, h2, h3, [role="heading"]') || []]
    .some(el => /^(?:create (?:an )?account|register|sign up)$/i.test(String(el.textContent || '').replace(/\s+/g, ' ').trim()));
  const accountLanguage = /\b(?:create (?:an )?account|register|sign up)\b/i.test(text);
  const otpLanguage = /verification code|security code|two.factor|multi.factor|authenticator|verify your identity|6-digit code|enter code|one-time code/i.test(text);
  const fileInput = root.querySelector?.('input[type="file"]');
  const visibleControls = [...root.querySelectorAll?.('input, textarea, select') || []]
    .filter(el => !['hidden', 'submit', 'button'].includes(String(el.type || '').toLowerCase()));
  // A Greenhouse application can include a human-verification code among
  // ordinary resume and identity fields. That is not a dedicated MFA
  // surface and must not skip the rest of the form or trip the MFA gate.
  const dedicatedMfaSurface = otpLanguage && !fileInput && visibleControls.length <= 6;
  return {
    login: /sign in|log in|password/i.test(text) && Boolean(root.querySelector?.('input[type="password"]')),
    mfa: dedicatedMfaSurface,
    captcha: captchaPrompt || visibleCaptchaFrame,
    accountCreation: accountControl || accountHeading || (Boolean(credentialInput) && accountLanguage),
    review: /review (?:your|application)|application review/i.test(text),
    // HTTP 200 means only that the ATS processed the request.  Some portals
    // return it for an explicit rejection (for example an anti-spam screen),
    // so a visible failure must always take precedence over success/network
    // evidence in the runner.
    submissionRejected: /(?:could(?: not|n't) submit|submission (?:was )?(?:flagged|rejected|failed)|application (?:was )?(?:flagged|rejected)|possible spam)/i.test(text),
    success: /application (?:has been )?(?:submitted|received)|thank you for applying/i.test(text),
    hasNext: /\b(next|continue|save and continue)\b/i.test(buttonText),
    hasSubmit: /\bsubmit application\b|\bsubmit\b/i.test(buttonText),
  };
}
